INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Dokumentation nur für Entwickler gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Admins und Nutzer"}, {"text": "Ja", "correct": false, "because": "Breitere Zielgruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die IT-Dokumentation?', 3, '[{"text": "Verständnis fördern", "correct": true, "because": "Prozesse erklären"}, {"text": "Kosten erhöhen", "correct": false, "because": "Effizienz im Fokus"}, {"text": "Code ersetzen", "correct": false, "because": "Ergänzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur IT-Dokumentation?', 5, '[{"text": "Systembeschreibungen", "correct": true, "because": "Technische Details"}, {"text": "Benutzerhandbücher", "correct": true, "because": "Anleitung"}, {"text": "Papierfarben", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Dokumentation erleichtert Wartung. b) Sie ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pflicht in Projekten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der IT-Dokumentation?', 4, '[{"text": "Klarheit", "correct": false, "because": "Verständnis nötig"}, {"text": "Aktualität", "correct": false, "because": "Relevanz wichtig"}, {"text": "Schriftartgröße", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Dokumentation nur schriftlich ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Diagramme"}, {"text": "Ja", "correct": false, "because": "Visuelle Elemente"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wird oft für Dokumentation genutzt?', 3, '[{"text": "Confluence", "correct": true, "because": "Wissensmanagement"}, {"text": "Photoshop", "correct": false, "because": "Bildbearbeitung"}, {"text": "Excel", "correct": false, "because": "Tabellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte gehören zur IT-Dokumentation?', 5, '[{"text": "Netzwerkpläne", "correct": true, "because": "Infrastruktur"}, {"text": "Code-Kommentare", "correct": true, "because": "Programmierung"}, {"text": "Kaffeerezepte", "correct": false, "because": "Kein IT-Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Dokumentation hilft bei Fehlersuche. b) Sie ist nur für Kunden. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch intern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine gute Dokumentation?', 4, '[{"text": "Struktur", "correct": false, "because": "Übersicht nötig"}, {"text": "Details", "correct": false, "because": "Relevanz wichtig"}, {"text": "Dekoration", "correct": true, "because": "Kein Faktor"}]'),
